INSERT INTO `assessment_questions` (`id`, `skill_id`, `question`, `options_json`, `correct_option_index`, `difficulty`, `source`, `is_active`, `created_by`, `created_at`, `updated_at`) VALUES
(1, 9, 'Apa perintah SQL yang digunakan untuk mengambil data dari tabel?', '[\"SELECT\", \"INSERT\", \"UPDATE\", \"DELETE\"]', 0, 'medium', 'ai', 1, 1, '2026-04-16 12:39:37', '2026-04-16 12:39:37'),
(2, 9, 'Bagaimana cara mengurutkan hasil query berdasarkan kolom tertentu?', '[\"ORDER BY\", \"GROUP BY\", \"SORT\", \"FILTER\"]', 0, 'medium', 'ai', 1, 1, '2026-04-16 12:39:37', '2026-04-16 12:39:37'),
(3, 9, 'Apa fungsi dari perintah JOIN dalam SQL?', '[\"Menggabungkan dua atau lebih tabel\", \"Menghapus data\", \"Memperbarui data\", \"Membuat tabel baru\"]', 0, 'medium', 'ai', 1, 1, '2026-04-16 12:39:37', '2026-04-16 12:39:37'),
(4, 9, 'Apa yang dilakukan perintah GROUP BY?', '[\"Mengelompokkan hasil berdasarkan kolom tertentu\", \"Mengambil data unik\", \"Mengurutkan data\", \"Menampilkan semua data\"]', 0, 'medium', 'ai', 1, 1, '2026-04-16 12:39:37', '2026-04-16 12:39:37'),
(5, 9, 'Apa yang dimaksud dengan primary key dalam tabel?', '[\"Kolom yang unik dan tidak boleh null\", \"Kolom yang dapat berisi nilai duplikat\", \"Kolom yang menyimpan data teks\", \"Kolom yang menyimpan data numerik\"]', 0, 'medium', 'ai', 1, 1, '2026-04-16 12:39:37', '2026-04-16 12:39:37'),
(6, 23, 'Apa fungsi dari alat \'Lasso\' di Adobe Photoshop?', '[\"Memilih area bebas dari gambar\", \"Menghapus latar belakang\", \"Menambahkan teks\", \"Membuat bentuk geometris\"]', 0, 'medium', 'ai', 1, 1, '2026-04-16 14:23:01', '2026-04-16 14:23:01'),
(7, 23, 'Bagaimana cara mengubah ukuran gambar tanpa mengubah rasio aspeknya?', '[\"Tekan Shift saat menarik sudut gambar\", \"Tekan Alt saat menarik sudut gambar\", \"Menggunakan menu \'Image Size\' tanpa centang \'Constrain Proportions\'\", \"Menggunakan alat \'Crop\'\"]', 0, 'medium', 'ai', 1, 1, '2026-04-16 14:23:01', '2026-04-16 14:23:01'),
(8, 23, 'Apa yang dimaksud dengan \'layer\' di Adobe Photoshop?', '[\"Bagian dari gambar yang dapat diedit secara terpisah\", \"Efek yang diterapkan pada gambar\", \"Format file gambar\", \"Alat untuk menggambar\"]', 0, 'medium', 'ai', 1, 1, '2026-04-16 14:23:01', '2026-04-16 14:23:01'),
(9, 23, 'Fungsi dari \'Clone Stamp Tool\' adalah?', '[\"Menggandakan bagian gambar dari satu area ke area lain\", \"Membuat teks baru\", \"Mengubah warna gambar\", \"Menambahkan efek blur\"]', 0, 'medium', 'ai', 1, 1, '2026-04-16 14:23:01', '2026-04-16 14:23:01'),
(10, 23, 'Apa yang dilakukan \'Adjustment Layer\' di Adobe Photoshop?', '[\"Mengubah warna dan kontras tanpa merusak gambar asli\", \"Menyimpan gambar dalam format baru\", \"Menghapus layer yang tidak diinginkan\", \"Menambahkan teks ke gambar\"]', 0, 'medium', 'ai', 1, 1, '2026-04-16 14:23:01', '2026-04-16 14:23:01');
