INSERT INTO `job_listings` (`id`, `company_id`, `created_by`, `industry_id`, `title`, `slug`, `description`, `responsibilities`, `required_qualifications`, `preferred_qualifications`, `benefits`, `location_city`, `location_province`, `work_mode`, `job_type`, `experience_level`, `qualification`, `experience_min_years`, `experience_max_years`, `salary_min`, `salary_max`, `salary_currency`, `is_salary_visible`, `is_anonymous`, `is_urgent`, `status`, `integrity_score`, `response_sla_hours`, `published_at`, `closes_at`, `created_at`, `updated_at`) VALUES
(1, 1, 14, 1, 'Backend Engineer', 'karivia-labs-backend-engineer', 'Demo role for testing candidate discovery, applications, analytics, and AI matching.', 'Own product delivery, collaborate with cross-functional teams, and improve platform quality.', 'Relevant experience, strong communication, and practical portfolio or project history.', 'Experience in high-growth teams and comfort working with data-informed decisions.', '<ul>\n    <li>BPJS Kesehatan & BPJS Ketenagakerjaan untuk karyawan dan keluarga</li>\n    <li>Tunjangan Hari Raya (THR) + bonus tahunan berbasis performa</li>\n    <li>Cuti tahunan 14 hari + unlimited sick leave</li>\n    <li>Asuransi kesehatan swasta dengan coverage rawat inap</li>\n    <li>Hardware allowance (laptop, monitor, peripheral) Rp15.000.000</li>\n    <li>Budget pengembangan diri Rp10.000.000/tahun (kursus, konferensi, buku)</li>\n    <li>Fleksibilitas jam kerja & opsi remote/hybrid</li>\n    <li>Stock option program untuk karyawan tetap</li>\n</ul>', 'Jakarta', 'DKI Jakarta', 'remote', 'full_time', 'entry', NULL, NULL, NULL, 7000000, 13000000, 'IDR', 0, 0, 0, 'suspended', 68, 24, '2026-04-15 05:52:01', '2026-05-06 05:52:01', '2026-04-16 05:52:01', '2026-04-26 20:27:42'),
(2, 2, 15, 2, 'Frontend Engineer', 'frontend-engineer', 'Demo role for testing candidate discovery, applications, analytics, and AI matching.', 'Own product delivery, collaborate with cross-functional teams, and improve platform quality.', 'Relevant experience, strong communication, and practical portfolio or project history.', 'Experience in high-growth teams and comfort working with data-informed decisions.<div><br></div><div><ol><li>Experience in high-growth teams and comfort working with data-informed decisions.</li><li>Experience in high-growth teams and comfort working with data-informed decisions.</li><li>Experience in high-growth teams and comfort working with data-informed decisions.</li></ol></div>', '<ul>\n    <li>BPJS Kesehatan & BPJS Ketenagakerjaan untuk karyawan dan keluarga</li>\n    <li>Tunjangan Hari Raya (THR) + bonus tahunan berbasis performa</li>\n    <li>Cuti tahunan 14 hari + unlimited sick leave</li>\n    <li>Asuransi kesehatan swasta dengan coverage rawat inap</li>\n    <li>Hardware allowance (laptop, monitor, peripheral) Rp15.000.000</li>\n    <li>Budget pengembangan diri Rp10.000.000/tahun (kursus, konferensi, buku)</li>\n    <li>Fleksibilitas jam kerja & opsi remote/hybrid</li>\n    <li>Stock option program untuk karyawan tetap</li>\n</ul>', 'Bandung', 'Jawa Barat', 'hybrid', 'contract', 'mid', NULL, NULL, NULL, 7500000, 13800000, 'IDR', 1, 0, 0, 'published', 69, 36, '2026-04-14 05:52:01', '2026-05-06 17:00:00', '2026-04-16 05:52:01', '2026-04-16 13:17:03'),
