(1, 1, 1, 4, 5, 1, '[{\"id\": \"q1\", \"options\": [\"Menganalisis masalah\", \"Mengabaikan masalah\", \"Mencari solusi cepat\", \"Bertanya kepada orang lain\"], \"question\": \"Apa langkah pertama yang harus dilakukan saat menghadapi masalah kompleks?\", \"correct_index\": 0, \"selected_index\": 0}, {\"id\": \"q2\", \"options\": [\"Mendengarkan satu sisi saja\", \"Membandingkan bukti yang ada\", \"Mengandalkan opini pribadi\", \"Mengabaikan data\"], \"question\": \"Bagaimana cara terbaik untuk mengevaluasi argumen yang berbeda?\", \"correct_index\": 1, \"selected_index\": 3}, {\"id\": \"q3\", \"options\": [\"Mencari penyebab kegagalan\", \"Menyerah dan tidak mencoba lagi\", \"Menyalahkan orang lain\", \"Mengabaikan masalah\"], \"question\": \"Apa yang harus dilakukan jika solusi yang diusulkan tidak berhasil?\", \"correct_index\": 0, \"selected_index\": 0}, {\"id\": \"q4\", \"options\": [\"Agar keputusan lebih cepat\", \"Agar keputusan lebih beragam dan tepat\", \"Karena semua orang harus setuju\", \"Karena itu lebih mudah\"], \"question\": \"Mengapa penting untuk mempertimbangkan sudut pandang yang berbeda dalam pengambilan keputusan?\", \"correct_index\": 1, \"selected_index\": 1}, {\"id\": \"q5\", \"options\": [\"Menerima informasi tanpa pertanyaan\", \"Menganalisis dan mengevaluasi informasi secara objektif\", \"Berpikir positif tanpa alasan\", \"Mengikuti pendapat mayoritas\"], \"question\": \"Apa yang dimaksud dengan berpikir kritis?\", \"correct_index\": 1, \"selected_index\": 1}]', '2026-04-16 11:33:32', '2026-04-16 11:33:32', '2026-04-16 11:33:32'),
(2, 3, 23, 1, 5, 0, '[{\"id\": \"bank-6\", \"options\": [\"Memilih area bebas dari gambar\", \"Menghapus latar belakang\", \"Menambahkan teks\", \"Membuat bentuk geometris\"], \"question\": \"Apa fungsi dari alat \'Lasso\' di Adobe Photoshop?\", \"correct_index\": 0, \"selected_index\": 1}, {\"id\": \"bank-10\", \"options\": [\"Mengubah warna dan kontras tanpa merusak gambar asli\", \"Menyimpan gambar dalam format baru\", \"Menghapus layer yang tidak diinginkan\", \"Menambahkan teks ke gambar\"], \"question\": \"Apa yang dilakukan \'Adjustment Layer\' di Adobe Photoshop?\", \"correct_index\": 0, \"selected_index\": 2}, {\"id\": \"bank-8\", \"options\": [\"Bagian dari gambar yang dapat diedit secara terpisah\", \"Efek yang diterapkan pada gambar\", \"Format file gambar\", \"Alat untuk menggambar\"], \"question\": \"Apa yang dimaksud dengan \'layer\' di Adobe Photoshop?\", \"correct_index\": 0, \"selected_index\": 3}, {\"id\": \"bank-7\", \"options\": [\"Tekan Shift saat menarik sudut gambar\", \"Tekan Alt saat menarik sudut gambar\", \"Menggunakan menu \'Image Size\' tanpa centang \'Constrain Proportions\'\", \"Menggunakan alat \'Crop\'\"], \"question\": \"Bagaimana cara mengubah ukuran gambar tanpa mengubah rasio aspeknya?\", \"correct_index\": 0, \"selected_index\": 2}, {\"id\": \"bank-9\", \"options\": [\"Menggandakan bagian gambar dari satu area ke area lain\", \"Membuat teks baru\", \"Mengubah warna gambar\", \"Menambahkan efek blur\"], \"question\": \"Fungsi dari \'Clone Stamp Tool\' adalah?\", \"correct_index\": 0, \"selected_index\": 0}]', '2026-04-18 22:41:52', '2026-04-18 22:41:52', '2026-04-18 22:41:52'),
(3, 3, 23, 1, 5, 0, '[{\"id\": \"bank-10\", \"options\": [\"Mengubah warna dan kontras tanpa merusak gambar asli\", \"Menyimpan gambar dalam format baru\", \"Menghapus layer yang tidak diinginkan\", \"Menambahkan teks ke gambar\"], \"question\": \"Apa yang dilakukan \'Adjustment Layer\' di Adobe Photoshop?\", \"correct_index\": 0, \"selected_index\": 1}, {\"id\": \"bank-7\", \"options\": [\"Tekan Shift saat menarik sudut gambar\", \"Tekan Alt saat menarik sudut gambar\", \"Menggunakan menu \'Image Size\' tanpa centang \'Constrain Proportions\'\", \"Menggunakan alat \'Crop\'\"], \"question\": \"Bagaimana cara mengubah ukuran gambar tanpa mengubah rasio aspeknya?\", \"correct_index\": 0, \"selected_index\": 2}, {\"id\": \"bank-9\", \"options\": [\"Menggandakan bagian gambar dari satu area ke area lain\", \"Membuat teks baru\", \"Mengubah warna gambar\", \"Menambahkan efek blur\"], \"question\": \"Fungsi dari \'Clone Stamp Tool\' adalah?\", \"correct_index\": 0, \"selected_index\": 1}, {\"id\": \"bank-6\", \"options\": [\"Memilih area bebas dari gambar\", \"Menghapus latar belakang\", \"Menambahkan teks\", \"Membuat bentuk geometris\"], \"question\": \"Apa fungsi dari alat \'Lasso\' di Adobe Photoshop?\", \"correct_index\": 0, \"selected_index\": 3}, {\"id\": \"bank-8\", \"options\": [\"Bagian dari gambar yang dapat diedit secara terpisah\", \"Efek yang diterapkan pada gambar\", \"Format file gambar\", \"Alat untuk menggambar\"], \"question\": \"Apa yang dimaksud dengan \'layer\' di Adobe Photoshop?\", \"correct_index\": 0, \"selected_index\": 0}]', '2026-04-18 22:48:43', '2026-04-18 22:48:43', '2026-04-18 22:48:43');
